import{_ as a,o as n,c as t,a0 as s}from"./chunks/framework.B_k70FqT.js";const g=JSON.parse('{"title":"What is LiteGraph","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":1795867940000}'),o={name:"en/guide/introduction.md"};function i(r,e,d,p,l,c){return n(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="what-is-litegraph" tabindex="-1">What is LiteGraph <a class="header-anchor" href="#what-is-litegraph" aria-label="Permalink to &quot;What is LiteGraph&quot;">​</a></h1><p>LiteGraph is a <strong>node-graph engine</strong> written in TypeScript: nodes, ports and links are drawn on an HTML5 Canvas, and a whole graph can be edited, executed and serialized. It is both a visual editor (drag nodes, wire links, edit properties) and a pure dataflow runtime (run graphs in the browser or in Node, no canvas required).</p><p>This repository is a TypeScript rewrite of <a href="https://github.com/jagenjo/litegraph.js" target="_blank" rel="noreferrer">jagenjo/litegraph.js</a> (with some reference to <a href="https://github.com/space-nuko/litegraph.ts" target="_blank" rel="noreferrer">space-nuko/litegraph.ts</a>), split into a pnpm monorepo: <strong>core engine + pluggable node packs + example apps + docs site</strong>. Unlike upstream, node packs here are separate npm packages you can install on demand; type checking runs with <code>strict</code>; builds ship ESM, UMD and <code>.d.ts</code>.</p><h2 id="what-you-can-build" tabindex="-1">What you can build <a class="header-anchor" href="#what-you-can-build" aria-label="Permalink to &quot;What you can build&quot;">​</a></h2><ul><li><strong>Visual scripting</strong>: split business logic into node graphs so non-programmers can wire and tune them in the browser.</li><li><strong>Data/signal flow editing</strong>: audio processing chains, MIDI generation, math, string handling and other built-in nodes compose directly.</li><li><strong>Live interfaces</strong>: <code>live_mode</code> hides the editor grid, node borders and ports, keeping only node-drawn content — ideal for dashboards and control panels.</li><li><strong>Graph as config</strong>: <code>graph.serialize()</code> yields plain JSON that you can store in a database, ship with your app, or use as a plugin format.</li><li><strong>Embedding in any web app</strong>: all it takes is a <code>&lt;canvas&gt;</code> and a container element; the core package has no implicit style dependency — styles are loaded explicitly through the <code>style.css</code> subpath.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LiteGraph (global registry + config)</span></span>
<span class="line"><span>├── LGraph            one graph: nodes, links, groups, I/O, execution loop, serialization</span></span>
<span class="line"><span>│   ├── LGraphNode    node base class: ports, widgets, properties, serialization, onExecute and other callbacks</span></span>
<span class="line"><span>│   ├── LLink         a link</span></span>
<span class="line"><span>│   └── LGraphGroup   a group box on the canvas</span></span>
<span class="line"><span>├── LGraphCanvas      canvas: events, rendering, UI (three mixins assembled into one class)</span></span>
<span class="line"><span>│   ├── DragAndScale  viewport zoom and pan</span></span>
<span class="line"><span>│   └── ContextMenu   context menu</span></span>
<span class="line"><span>└── Built-in nodes    GraphInput, GraphOutput, Subgraph</span></span></code></pre></div><p>Key design decisions:</p><ul><li><strong>Registry pattern</strong>: node types register into <code>LiteGraph.registered_node_types</code> at runtime. <code>LiteGraph.use(install)</code> installs a node pack and deduplicates, while <code>LiteGraph.registerNodeType()</code> handles a single registration and fills in <code>category</code> and a default title. Node packs therefore never import each other — they depend only on core.</li><li><strong>Classes + interface declaration merging + <code>applyMixins</code></strong>: <code>LGraphCanvas</code> mixes prototype methods from the event, rendering and UI files into itself, avoiding 42 hand-written wrapper methods; at the type level it is still one complete class.</li><li><strong>Dataflow + event flow</strong>: regular ports pass values through <code>getInputData()</code> / <code>setOutputData()</code>; ports typed <code>event</code> (<code>BuiltInSlotType.EVENT</code>) carry actions and trigger <code>onAction</code>.</li><li><strong>Execution order</strong>: <code>LGraph.computeExecutionOrder()</code> topologically sorts nodes by link dependencies; <code>graph.start()</code> calls <code>onExecute</code> on runnable nodes each frame, and <code>graph.stop()</code> ends the loop.</li><li><strong>Two canvases</strong>: <code>LGraphCanvas</code> keeps a background layer and an interaction layer; <code>draw()</code> paints the background first and the foreground second, so static content is not redrawn every frame.</li></ul><h2 id="package-matrix" tabindex="-1">Package matrix <a class="header-anchor" href="#package-matrix" aria-label="Permalink to &quot;Package matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Description</th><th>Nodes</th></tr></thead><tbody><tr><td><code>@gausszhou/litegraph-core</code></td><td>Engine core: registry, graph, node, canvas, link, group, subgraph, built-in graph nodes</td><td>3</td></tr><tr><td><code>@gausszhou/litegraph</code></td><td>Aggregate package: installs every node pack and re-exports all core APIs and styles</td><td>—</td></tr><tr><td><code>@gausszhou/litegraph-nodes-basic</code></td><td>Constants, watch, reroute, time, comparison, array access</td><td>16</td></tr><tr><td><code>@gausszhou/litegraph-nodes-math</code></td><td>Math operations, rounding, random, approximate equality</td><td>5</td></tr><tr><td><code>@gausszhou/litegraph-nodes-logic</code></td><td>And / or / not, comparison, branch, selector</td><td>8</td></tr><tr><td><code>@gausszhou/litegraph-nodes-strings</code></td><td>String concatenation, JSON parse / stringify, comparison, replace</td><td>12</td></tr><tr><td><code>@gausszhou/litegraph-nodes-events</code></td><td>Timer, delay, filter, log, branch</td><td>10</td></tr><tr><td><code>@gausszhou/litegraph-nodes-input</code></td><td>Gamepad input</td><td>1</td></tr><tr><td><code>@gausszhou/litegraph-nodes-widget</code></td><td>Control nodes: button, toggle, slider, knob, progress bar, panel and more</td><td>10</td></tr><tr><td><code>@gausszhou/litegraph-nodes-graphics</code></td><td>Curve plotting</td><td>1</td></tr><tr><td><code>@gausszhou/litegraph-nodes-audio</code></td><td>Web Audio nodes: oscillator, filter, delay, reverb, oscilloscope and more</td><td>17</td></tr><tr><td><code>@gausszhou/litegraph-nodes-midi</code></td><td>MIDI input / output, generation, quantize, transpose</td><td>12</td></tr></tbody></table><p>The three core built-in nodes are <code>graph/input</code>, <code>graph/output</code> and <code>graph/subgraph</code>; the 10 node packs add 92 nodes, for <strong>95 node types</strong> in total. See the <a href="/litegraph/docs/en/nodes/">node catalog</a> for the full list.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>  core/            engine core (depends on no node pack)</span></span>
<span class="line"><span>  litegraph/       aggregate package (core + all node packs)</span></span>
<span class="line"><span>  nodes-basic/     ┐</span></span>
<span class="line"><span>  nodes-math/      │</span></span>
<span class="line"><span>  nodes-logic/     │</span></span>
<span class="line"><span>  nodes-strings/   ├ 10 node packs, each depending only on core</span></span>
<span class="line"><span>  nodes-events/    │</span></span>
<span class="line"><span>  nodes-input/     │</span></span>
<span class="line"><span>  nodes-widget/    │</span></span>
<span class="line"><span>  nodes-graphics/  │</span></span>
<span class="line"><span>  nodes-audio/     │</span></span>
<span class="line"><span>  nodes-midi/      ┘</span></span>
<span class="line"><span>  tests/           cross-package tests: core paths, node contracts, interaction, example snapshots</span></span>
<span class="line"><span>apps/</span></span>
<span class="line"><span>  editor/          full demo editor (toolbar, example dropdown, mini preview, live mode)</span></span>
<span class="line"><span>  example-minimal/ minimal integration example</span></span>
<span class="line"><span>docs/              VitePress docs site</span></span>
<span class="line"><span>scripts/           build / verification / docs generation scripts</span></span></code></pre></div><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>LiteGraph handles the graph itself: node management, links, execution scheduling, canvas interaction and serialization. The following is up to you or to your nodes:</p><ul><li>node behaviour (<code>onExecute</code>, <code>onDrawForeground</code>, <code>onAction</code> and other callbacks);</li><li>the concrete rendering backend (core is Canvas2D only; <code>enableWebGL()</code> is currently a no-op — see the <a href="/litegraph/docs/en/guide/contributing.html#roadmap">roadmap</a>);</li><li>persistence and permissions (serialization yields JSON; where it lives and who may change it is the app&#39;s decision);</li><li>DOM dependency in the headless runtime: the core entry point never touches <code>window</code> implicitly, but <code>LGraphCanvas</code> still needs a DOM.</li></ul><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/litegraph/docs/en/guide/getting-started.html">Getting Started</a>: run the editor or the minimal example in 5 minutes.</li><li><a href="/litegraph/docs/en/guide/packages.html">Packages &amp; Imports</a>: import core, a single node pack or the aggregate package.</li><li><a href="/litegraph/docs/en/nodes/">Node Catalog</a>: inputs, outputs, widgets and properties for all 95 node types.</li><li><a href="/litegraph/docs/en/api/">API Reference</a>: public API docs generated from source.</li></ul>`,19)])])}const u=a(o,[["render",i]]);export{g as __pageData,u as default};
